# AUTOGENERATED! DO NOT EDIT!

from pathlib import Path

from .. import const
from .._models import BoxMeta, BoxPart, get_boxyard_meta
from .._remote_index import find_remote_box_by_id
from .._utils.locking import (
    BOX_SYNC_LOCK_TIMEOUT,
    BoxyardLockManager,
    acquire_lock_async,
)
from .._utils.sync_helper import SyncDirection, SyncSetting, sync_helper
from ..config import get_config, StorageType

async def discard_local(
    config_path: Path,
    box_index_name: str,
    verbose: bool = True,
    show_rclone_progress: bool = False,
) -> Path:
    """
    Replace this machine's copy of a box's DATA with the remote's.

    Args:
        config_path: Path to the boxyard config file.
        box_index_name: Index name of the box.
        verbose: Print what happened, including where the discarded work went.
        show_rclone_progress: Show rclone progress during the pull.

    Returns:
        The directory holding what was overwritten.
    """
    config = get_config(config_path)
    
    boxyard_meta = get_boxyard_meta(config)
    if box_index_name not in boxyard_meta.by_index_name:
        raise ValueError(f"Box '{box_index_name}' not found.")
    
    box_meta = boxyard_meta.by_index_name[box_index_name]
    
    if box_meta.get_storage_location_config(config).storage_type == StorageType.LOCAL:
        raise ValueError(
            f"Box '{box_index_name}' is in local storage location "
            f"'{box_meta.storage_location}'; there is no remote copy to take."
        )
    
    from boxyard._checkout import get_box_checkout_status, LocalCheckoutState, CheckoutRootUnavailable
    
    _checkout = get_box_checkout_status(config, box_meta)
    if _checkout.state == LocalCheckoutState.UNAVAILABLE:
        raise CheckoutRootUnavailable(
            f"Cannot discard '{box_index_name}': checkout root "
            f"'{_checkout.checkout_root}' is unavailable."
        )
    if _checkout.state != LocalCheckoutState.INCLUDED:
        raise ValueError(
            f"Box '{box_index_name}' checkout state is {_checkout.state.value}; there is "
            "no complete local checkout whose changes can be discarded."
        )
    _remote_index_name = await find_remote_box_by_id(
        config, box_meta.storage_location, box_meta.box_id
    )
    if _remote_index_name is None:
        _remote_index_name = box_index_name
    
    _sl_config = box_meta.get_storage_location_config(config)
    _remote_base = (
        _sl_config.store_path / const.REMOTE_BOXES_REL_PATH / _remote_index_name
    )
    
    _conf_path = box_meta.get_local_part_path(config, BoxPart.CONF)
    _include_path = _conf_path / const.RCLONE_INCLUDE_FILENAME
    _exclude_path = _conf_path / const.RCLONE_EXCLUDE_FILENAME
    _filters_path = _conf_path / const.RCLONE_FILTERS_FILENAME
    _include_path = _include_path if _include_path.exists() else None
    _exclude_path = (
        _exclude_path if _exclude_path.exists() else config.default_rclone_exclude_path
    )
    _filters_path = _filters_path if _filters_path.exists() else None
    
    _lock_manager = BoxyardLockManager(config.boxyard_data_path)
    _lock_path = _lock_manager.box_sync_lock_path(box_index_name)
    _lock_manager._ensure_lock_dir(_lock_path)
    _sync_lock = __import__("filelock").FileLock(_lock_path, timeout=0)
    await acquire_lock_async(
        _sync_lock, f"box sync ({box_index_name})", _lock_path, BOX_SYNC_LOCK_TIMEOUT
    )
    try:
        await sync_helper(
            rclone_config_path=config.rclone_config_path,
            sync_direction=SyncDirection.PULL,
            sync_setting=SyncSetting.FORCE,
            local_path=box_meta.get_local_part_path(config, BoxPart.DATA),
            local_sync_record_path=box_meta.get_local_sync_record_path(config, BoxPart.DATA),
            remote=box_meta.storage_location,
            remote_path=_remote_base / const.BOX_DATA_REL_PATH,
            remote_sync_record_path=(
                _sl_config.store_path
                / const.SYNC_RECORDS_REL_PATH
                / _remote_index_name
                / f"{BoxPart.DATA.value}.rec"
            ),
            local_sync_backups_path=config.local_sync_backups_path,
            remote_sync_backups_path=_sl_config.store_path / const.REMOTE_BACKUP_REL_PATH,
            include_path=_include_path,
            exclude_path=_exclude_path,
            filters_path=_filters_path,
            # The point of the command: what is thrown away must be recoverable.
            delete_backup=False,
            verbose=False,
            show_rclone_progress=show_rclone_progress,
            preserve_exec_perms=True,
        )
    finally:
        _sync_lock.release()
    backups_path = config.local_sync_backups_path
    
    if verbose:
        print(
            f"Discarded this machine's local changes to '{box_index_name}' and took "
            f"the remote copy.\n"
            f"What was overwritten is under '{backups_path}' — nothing was deleted "
            f"outright. Look there before assuming the work is gone."
        )
    return backups_path
